        .forum-header-title { font-size: 48px; color: #D90000; text-align: center; margin-bottom: 20px; } .forum-post-list { max-width: 800px; margin: 0 auto; padding-top: 50px; } .forum-post { background-color: #D90000; padding: 3px; margin-bottom: 25px; clip-path: polygon(0 0, 100% 0, 100% 90%, 10% 90%, 0 100%); } .forum-post-inner { background-color: black; padding: 15px 20px; } .post-title { font-size: 22px; color: #ffdd57; } .post-meta { font-size: 14px; color: #aaa; margin: 10px 0; } .post-content {white-space: pre-wrap;} .post-footer {display: flex; justify-content: flex-end; align-items: center; color: #ff5252;} .post-comments{margin-top: 15px; border-top: 1px dashed #444; padding-top: 15px;} .comment-item{background: #222; padding: 10px; margin-bottom: 10px; border-left: 3px solid #D90000;} .commenter{color:#76c7c0;}
