        .activity-log-container { background: rgba(0,0,0,0.7); } .activity-log-main-title { position: relative; width: 320px; margin: 0 auto 10px auto; padding: 10px 20px; background-color: white; color: black; border: 3px solid black; text-align: center; transform: skewX(-10deg); } .activity-log-main-title h1 { margin: 0; font-size: 28px; color: white; text-shadow: -1.5px -1.5px 0 #000, 1.5px -1.5px 0 #000, -1.5px 1.5px 0 #000, 1.5px 1.5px 0 #000; transform: skewX(10deg); } .activity-log-subtitle { text-align: center; color: #ccc; margin-bottom: 30px; } .activity-panels-wrapper { position: relative; width: 100%; min-height: 480px; max-width: 750px; margin: auto; } .activity-panel { background-color: #1a1a1a; padding: 15px; position: absolute; } .activity-panel h2 { margin: 0 0 10px 0; font-size: 24px; display: flex; justify-content: space-between; align-items: baseline; } .activity-panel h2 .percentage { font-family: 'Anton', sans-serif; font-size: 42px; } .activity-panel ul { list-style: none; padding-left: 5px; margin: 0; } .activity-panel ul li::before { content: "・"; margin-right: 5px; } .thief-activities { color: #FF1E1E; top: 0; left: 0; width: 250px; clip-path: polygon(0% 15%, 15% 0%, 85% 0%, 100% 10%, 100% 85%, 80% 100%, 20% 100%, 0% 90%); } .daily-life { color: #FFD93D; top: 130px; left: 30px; width: 280px; clip-path: polygon(10% 0%, 90% 0%, 100% 20%, 100% 80%, 85% 100%, 15% 100%, 0% 85%, 0% 15%); } .coop-activities { color: #4DABFF; top: 20px; right: 0; width: 320px; clip-path: polygon(0% 0%, 80% 5%, 100% 15%, 95% 90%, 85% 100%, 10% 95%, 0% 80%, 5% 20%); } .central-dagger { position: absolute; left: 45%; top: 280px; transform: translateX(-50%) rotate(15deg); font-size: 40px; } .bottom-elements-wrapper { position: absolute; bottom: 0; right: 30px; text-align: right; }

        /* --- Main Content Panel --- */
        .main-content-panel-wrapper { padding-top: 180px; width: 65%; max-width: 700px; margin: 0 auto; display: none; }
        .main-content-panel { background-color: rgba(15, 15, 15, 0.92); border: 2px solid #700000; padding: 20px; text-shadow: 1px 1px 1px #000; }
