        .main-content-panel .content-body { font-size: 17px; line-height: 1.9; color: #F0F0F0; } .main-content-panel .content-body pre { white-space: pre-wrap; word-wrap: break-word; font-family: inherit; color: inherit; }

        /* --- MEDIA QUERIES FOR MOBILE --- */
        @media (max-width: 767px) {
            :root { --p5-padding: 15px; }
            .p5-ui-container { padding: 0; padding-bottom: var(--mobile-bottom-nav-height); }
