            .sns-toggle-button .notification-badge { width: 20px; height: 20px; font-size: 12px; }

            .panel { padding: var(--p5-padding); padding-bottom: calc(var(--mobile-bottom-nav-height) + 20px); }
            .panel .return-button { top: auto; bottom: calc(var(--mobile-bottom-nav-height) + 15px); right: var(--p5-padding); }
            .coop-list, .forum-post-list, .message-list { width: 100%; padding-top: 20px; margin: 0; }
            .activity-panels-wrapper { min-height: initial; }
            .activity-panel { position: relative; width: 100%; top: auto; left: auto; right: auto; margin-bottom: 20px; clip-path: none; }
            .central-dagger, .bottom-elements-wrapper { display: none; }
        }
