            </div>
        </div>

        <!-- Pop-up Panels -->
        <div class="panel sns-messages-container" id="snsMessagesContainer"><ul class="message-list" id="messageList"></ul><div class="return-button">返回</div></div>
        <div class="panel activity-log-container" id="activityLogContainer"><div class="activity-log-main-title"><h1>大家的行动记录</h1></div><div class="activity-log-subtitle" id="activityLogDateSubtitle"></div><div class="activity-panels-wrapper"><div class="activity-panel thief-activities"><h2>怪盗行动 <span class="percentage" id="thiefActivityPercentage"></span></h2><ul id="thiefActivityList"></ul></div><div class="activity-panel daily-life"><h2>日常生活 <span class="percentage" id="dailyLifePercentage"></span></h2><ul id="dailyLifeList"></ul></div><div class="activity-panel coop-activities"><h2>COOP活动 <span class="percentage" id="coopActivityPercentage"></span></h2><ul id="coopActivityList"></ul></div><div class="central-dagger">†</div><div class="bottom-elements-wrapper"><div class="average-level-bubble" id="averageLevelTextElem"></div><div class="player-level"><span id="playerLevelPrefixElem"></span> <span id="playerLevelValueElem"></span></div></div></div><div class="return-button">返回</div></div>
        <div class="panel phantom-forum-container" id="phantomForumContainer"><h1 class="forum-header-title">怪盗团粉丝网站</h1><div class="forum-post-list" id="forumPostList"></div><div class="return-button">返回</div></div>
        <div class="panel coop-container" id="coopContainer"><ul class="coop-list" id="coopList"></ul><div class="return-button">返回</div></div>

        <!-- Navigation Buttons -->
        <div class="left-button-cluster">
            <div class="p5-button sns-toggle-button" id="snsToggleButton">SNS<span class="notification-badge" id="snsNotificationCount">0</span></div>
            <div class="p5-button activity-log-toggle-button" id="activityLogToggleButton">行动<br>记录</div>
            <div class="p5-button forum-toggle-button" id="forumToggleButton"></div>
            <div class="p5-button coop-toggle-button" id="coopToggleButton"></div>
        </div>
    </div>
    <script>
        // --- Configuration & Element Caching ---
        const GITHUB_PAGES_BASE_URL = 'https://cnfh1746.github.io/pp5/img/';
        const BACKGROUND_IMAGE_FILENAMES = ['e1.png', 'e2.png', 'e3.png', 'e4.png', 'e5.png', 'e6.png', 'e7.png', 'e8.png', 'e9.png', 'e10.png', 'e11.png', 'e12.png'];
        const SNS_AVATAR_MAP = { "主角": "changebtn1.png", "Joker": "changebtn1.png", "坂本龙司": "changebtn2.png", "龙司": "changebtn2.png", "高卷杏": "changebtn3.png", "杏": "changebtn3.png", "新岛真": "changebtn4.png", "真": "changebtn4.png", "奥村春": "changebtn5.png", "春": "changebtn5.png", "芳泽霞": "changebtn6.png", "芳泽堇": "changebtn6.png", "霞": "changebtn6.png", "堇": "changebtn6.png", "摩尔加纳": "changebtn7.png", "Mona": "changebtn7.png", "佐仓双叶": "changebtn9.png", "双叶": "changebtn9.png", "明智吾郎": "changebtn10.png", "明智": "changebtn10.png", "喜多川祐介": null, "学校系统": null, "老师": null, "伊格尔": null, "未知来源": null, "DEFAULT_TEXT_FALLBACK": true };
        let parsedPanelData = {}; const el = (id) => document.getElementById(id);

        function manageP5Music(filename) { let audioPlayer = document.getElementById('p5_ui_audio_player'); if (!audioPlayer) { audioPlayer = document.createElement('audio'); audioPlayer.id = 'p5_ui_audio_player'; audioPlayer.loop = true; audioPlayer.style.display = 'none'; document.body.appendChild(audioPlayer); } if (filename && filename.trim() !== "") { const fileSource = filename.startsWith('http') ? filename : `https://files.catbox.moe/${filename}`; if (audioPlayer.src !== fileSource) { audioPlayer.src = fileSource; audioPlayer.load(); } audioPlayer.play().catch(e => console.error("Audio play failed:", e)); } else { audioPlayer.pause(); } }

        function parseAIDataToStructuredObject(dataString) {
            const lines = (dataString || "").trim().split('\n');
            const data = { SNS消息列表: [], 行动记录怪盗条目列表: [], 行动记录日常条目列表: [], 行动记录COOP条目列表: [], 怪盗论坛帖子列表: [], Coop列表: [] };
            let capturingHTML = false; let htmlContentBuffer = "";
            const knownKeys = ['音乐文件名','面板标语','当前日期','当前星期','当前时段','当前天气图标','当前天气描述','背景图片URL','背景图片标识','目标倒计时描述','目标倒计时天数','目标内容','SNS通知数量','SNS消息数量','怪盗论坛帖子数量','行动记录日期副标题','行动记录怪盗百分比','行动记录怪盗条目数量','行动记录日常百分比','行动记录日常条目数量','行动记录COOP百分比','行动记录COOP条目数量','行动记录队伍平均等级描述','行动记录玩家等级前缀','行动记录玩家等级数值','主内容面板标题', 'Coop列表数量'];

            for (let i = 0; i < lines.length; i++) {
                const line = lines[i];
                if (capturingHTML) { const pnm = line.trimStart().match(/^([^:]+):\s*(.*)$/); let isKnownKey = false; if (pnm) { const pk = pnm[1].trim(); if (knownKeys.includes(pk) || pk.startsWith("SNS消息_") || pk.startsWith("行动记录") || pk.startsWith("怪盗论坛帖子_") || pk.startsWith("Coop列表_")) isKnownKey = true; } if (isKnownKey) { data.主内容面板HTML = htmlContentBuffer.trimEnd(); htmlContentBuffer = ""; capturingHTML = false; i--; continue; } else { htmlContentBuffer += line + '\n'; if (i === lines.length - 1) data.主内容面板HTML = htmlContentBuffer.trimEnd(); continue; } }
                const trimmedLine = line.trim(); if (!trimmedLine) continue;
                const parts = trimmedLine.match(/^([^:]+):\s*(.*)$/); if (!parts) continue;
                const key = parts[1].trim(); let value = parts[2].trim(); let jk = key.replace(/\s/g, '');

                if (key === '主内容面板HTML') { capturingHTML = true; htmlContentBuffer = value + '\n'; if (i === lines.length - 1) data.主内容面板HTML = htmlContentBuffer.trimEnd(); }
                else if (key.startsWith("SNS消息_")) { const mi = key.match(/SNS消息_(\d+)_/); if (!mi) continue; const mn = parseInt(mi[1]) - 1; if (mn >= 0 && data.SNS消息列表.length <= mn) for(let k=data.SNS消息列表.length; k<=mn; ++k) data.SNS消息列表.push({ 子消息列表: []}); const item = data.SNS消息列表[mn]; const sk = key.substring(mi[0].length); if (sk.startsWith("子消息_")) { const smi = sk.match(/子消息_(\d+)_/); if(!smi) continue; const smn = parseInt(smi[1]) - 1; if (smn >= 0 && item.子消息列表.length <= smn) for(let k=item.子消息列表.length; k<=smn; ++k) item.子消息列表.push({}); const subItem = item.子消息列表[smn]; const sik = sk.substring(smi[0].length); if (sik === "发送者") subItem.发送者 = value; else if (sik === "内容") subItem.内容 = value; } else { if (sk === "发送者") item.发送者 = value; else if (sk === "日期") item.日期 = value; else if (sk === "预览文本") item.预览文本 = value; else if (sk === "是否新消息") item.是否新消息 = value.toLowerCase() === 'true'; else if (sk === "是否默认选中") item.是否默认选中 = value.toLowerCase() === 'true'; else if (sk === "子消息数量") item.子消息数量 = parseInt(value) || 0; } }
                else if (key.startsWith("怪盗论坛帖子_")) { const postMatch = key.match(/怪盗论坛帖子_(\d+)_/); if (!postMatch) continue; const postIndex = parseInt(postMatch[1]) - 1; if (postIndex >= 0 && data.怪盗论坛帖子列表.length <= postIndex) for(let k=data.怪盗论坛帖子列表.length; k<=postIndex; ++k) data.怪盗论坛帖子列表.push({ 评论列表: [] }); const post = data.怪盗论坛帖子列表[postIndex]; const subKey = key.substring(postMatch[0].length); if (subKey.startsWith("评论_")) { const commentMatch = subKey.match(/评论_(\d+)_/); if (!commentMatch) continue; const commentIndex = parseInt(commentMatch[1]) - 1; if (commentIndex >= 0 && post.评论列表.length <= commentIndex) for(let k=post.评论列表.length; k<=commentIndex; ++k) post.评论列表.push({}); const comment = post.评论列表[commentIndex]; const commentSubKey = subKey.substring(commentMatch[0].length); if (commentSubKey === "评论者") comment.评论者 = value; else if (commentSubKey === "内容") comment.内容 = value; } else { if (subKey === "ID") post.ID = value; else if (subKey === "贴主") post.贴主 = value; else if (subKey === "标题") post.标题 = value; else if (subKey === "内容") post.内容 = value; else if (subKey === "赞") post.赞 = value; else if (subKey === "评论数量") post.评论数量 = parseInt(value) || 0; } }
                else if (key.startsWith("行动记录")) { const tm = key.match(/行动记录(怪盗|日常|COOP)条目_(\d+)/); if (tm) { const lt = tm[1]; const ei = parseInt(tm[2]) - 1; let tl; if (lt === "怪盗") tl = data.行动记录怪盗条目列表; else if (lt === "日常") tl = data.行动记录日常条目列表; else tl = data.行动记录COOP条目列表; if(ei >= 0 && tl.length <= ei) for(let k=tl.length; k<=ei; ++k) tl.push({}); tl[ei] = { 内容: value }; } else { if(knownKeys.includes(key)) data[jk] = value; } }
                else if (key.startsWith("Coop列表_")) { const coopMatch = key.match(/Coop列表_(\d+)_/); if (!coopMatch) continue; const coopIndex = parseInt(coopMatch[1]) - 1; if (coopIndex >= 0 && data.Coop列表.length <= coopIndex) for(let k=data.Coop列表.length; k<=coopIndex; ++k) data.Coop列表.push({}); const coop = data.Coop列表[coopIndex]; const subKey = key.substring(coopMatch[0].length); if (subKey === "姓名") coop.姓名 = value; else if (subKey === "秘仪") coop.秘仪 = value; else if (subKey === "等级") coop.等级 = value; }
                else if (knownKeys.includes(key)) { data[jk] = value; }
            }
            if (capturingHTML && htmlContentBuffer.trimEnd() !== "") data.主内容面板HTML = htmlContentBuffer.trimEnd();
            return data;
        }

        function populateText(elementId, text, defaultValue = "") { const elem = el(elementId); if (elem) elem.textContent = text || defaultValue; }
        function populateHTML(elementId, html, defaultValue = "") { const elem = el(elementId); if (elem) elem.innerHTML = html || defaultValue; }

        function updateAllUI(d) {
            manageP5Music(d.音乐文件名); let u; if (d.背景图片URL && d.背景图片URL.trim()) u = `url('${d.背景图片URL}')`; else { const id = d.背景图片标识 || 'random'; const fn = id === 'random' ? BACKGROUND_IMAGE_FILENAMES[Math.floor(Math.random() * BACKGROUND_IMAGE_FILENAMES.length)] : BACKGROUND_IMAGE_FILENAMES.includes(id) ? id : BACKGROUND_IMAGE_FILENAMES[0]; u = `url('${GITHUB_PAGES_BASE_URL}${fn}')`; } document.body.style.backgroundImage = u;
            if (el('forumToggleButton')) el('forumToggleButton').style.backgroundImage = `url('${GITHUB_PAGES_BASE_URL}phantom.png')`; if (el('coopToggleButton')) el('coopToggleButton').style.backgroundImage = `url('${GITHUB_PAGES_BASE_URL}p5r.png')`;
